<script setup lang="ts">import {ref,onMounted} from 'vue';import {datasets} from '../stores/datasets';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';const name=ref(''),text=ref(''),description=ref(''),selected=ref('');const {error,busy,act}=useTask();onMounted(datasets.load);async function file(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f)text.value=await f.text()}function submit(){act(async()=>{await datasets.create({name:name.value,csv_text:text.value,description:description.value});name.value='';text.value=''})}</script><template><PageHeading eyebrow="OBSERVATIONS / 01" title="里程碑观测台账" note="CSV字段：shipment_id,station,milestone,timestamp。时间必须携带时区，未知里程碑拒绝导入。"/><div class="two-col"><section><h2>已入库批次</h2><Notice :message="datasets.error.value"/><EmptyState v-if="!datasets.items.value.length"/><button v-for="row in datasets.items.value" class="record-row" :key="row.id" @click="selected=row.id"><div><h3>{{row.name}}</h3><p>{{row.events.length}}条事件 · {{row.description}}</p></div><span>{{selected===row.id?'收起/预览':'查看原始事件 ↗'}}</span></button><div v-for="row in datasets.items.value.filter(r=>r.id===selected)" :key="row.id" class="table-wrap"><table><thead><tr><th>票号</th><th>站点</th><th>里程碑</th><th>带时区时间</th></tr></thead><tbody><tr v-for="(e,i) in row.events.slice(0,15)" :key="i"><td>{{e.shipment_id}}</td><td>{{e.station}}</td><td>{{e.milestone}}</td><td>{{e.timestamp}}</td></tr></tbody></table><p>预览前15条，计算使用全部事件。</p></div></section><form v-if="canWrite()" @submit.prevent="submit" class="editor-panel"><h2>上传观测</h2><label>批次名称<input v-model="name" required minlength="2" placeholder="如：城配里程碑 11月10日"></label><label>CSV 文件<input type="file" accept=".csv" @change="file"></label><label>或粘贴CSV<textarea v-model="text" rows="8" required placeholder="shipment_id,station,milestone,timestamp"></textarea></label><label>口径说明<input v-model="description" placeholder="记录来源和时区"></label><Notice :message="error"/><button :disabled="busy">校验并入库</button></form><aside v-else class="field-note">当前是只读账号，可浏览原始事件；上传需要分析师权限。</aside></div></template>
